#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n+1,0);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
vector<int>st;long long best=0;
for(int i=0;i<=n;++i){
while(!st.empty()&&a[st.back()]>a[i]){
int j=st.back();st.pop_back();
int left=st.empty()?-1:st.back();
best=max(best,a[j]*(i-left-1));}
st.push_back(i);}
printf("%lld\n",best);return 0;}

